-- SafetyTraining v20.071
-- Datore di lavoro 16h + aggiornamento 6h authored/evidence completion.
-- Draft-only. Published compositions and Test Builder are intentionally untouched.
-- The general update is separated from the conditional Cantieri module.

insert into public.training_sources(source_key,authority,title,source_type,canonical_url,publication_date,checked_on,license_kind,reuse_policy,normative_status,topics,notes,metadata)
values
('inail-sgsl','INAIL','Sistemi di gestione della salute e sicurezza sul lavoro (SGSL)','institutional_technical','https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/migliorare-la-salute-e-la-sicurezza/sgsl.html',date '2012-12-10',date '2026-10-16','institutional_terms','facts_and_original_didactic_rewrite','supporting',array['SGSL','sistemi di gestione','organizzazione','miglioramento continuo','articolo 30'],'Riferimento INAIL per struttura, logica organizzativa e miglioramento continuo dei sistemi di gestione SSL; contenuti SafetyTraining riscritti in modo originale.',jsonb_build_object('priority','high_evidence')),
('inail-mog-art30-2026','INAIL','MOG art. 30 d.lgs. 81/08 - casi tipo e criteri applicativi','institutional_technical','https://www.inail.it/portale/prevenzione-e-sicurezza/it/focus/bando-isi---strumenti-informativi/progetti/asse-1-2---progetti-per-l-adozione-di-modelli-organizzativi-e-di/c---mog-art-30-dlgs-81-08.html',date '2026-04-09',date '2026-10-16','institutional_terms','facts_and_original_didactic_rewrite','supporting',array['MOG','articolo 30','d.lgs. 81/2008','governance','asseverazione'],'Riferimento INAIL 2026 per MOG ex art. 30; usare criteri e casi come evidence, senza riprodurre testi o allegati.',jsonb_build_object('priority','high_evidence'))
on conflict (source_key) do update set authority=excluded.authority,title=excluded.title,source_type=excluded.source_type,canonical_url=excluded.canonical_url,publication_date=excluded.publication_date,checked_on=excluded.checked_on,license_kind=excluded.license_kind,reuse_policy=excluded.reuse_policy,normative_status=excluded.normative_status,topics=excluded.topics,notes=excluded.notes,metadata=excluded.metadata,updated_at=now();

insert into public.learning_units(stable_key,title,summary,default_minutes,source_group,tags,active,metadata)
values('agg-datore:governance-riesame','ADL06 · Governance e riesame del sistema di prevenzione','Chiusura dell’aggiornamento generale del datore di lavoro: priorità, risorse, responsabilità, indicatori, azioni e riesame. Il modulo Cantieri resta separato e condizionale.',60,'agg_datore_lavoro',array['datore-lavoro','aggiornamento','asr-2025','dynamic','governance'],true,jsonb_build_object('dynamic_update',true,'didactic_version','datore-authored-v3','regulatory_basis','Accordo Stato-Regioni 17/04/2025 Rep. 59/CSR','replacement_for','agg-datore:governance-cantieri-riesame','construction_module_separated',true,'review_required',true))
on conflict (stable_key) do update set title=excluded.title,summary=excluded.summary,default_minutes=excluded.default_minutes,source_group=excluded.source_group,tags=excluded.tags,metadata=excluded.metadata,updated_at=now();

with authored(stable_key,focus,scenario,errors,source_keys) as (
 values
 ('datore:ruolo-contesto-sistema','Dal ruolo formale ai poteri effettivi: struttura, autonomia, risorse e decisioni prevenzionistiche devono essere coerenti.','Nuova sede con autonomia di spesa locale ma personale e acquisti centralizzati: mappare chi decide e quali poteri devono essere esplicitati.',jsonb_build_array('Confondere qualifica formale ed effettività del ruolo.','Lasciare ambigui i poteri dopo una riorganizzazione.','Trattare la sicurezza come funzione trasferibile integralmente ad altri.'),jsonb_build_array('normattiva-dlgs81-vigente','mlps-asr-2025','piemonte-indicazioni-formazione-2025')),
 ('datore:soggetti-obblighi-nondelegabili','Distinguere compiti delle figure della prevenzione, obblighi del datore e presidio delle funzioni non delegabili.','RSPP e consulente preparano il DVR ma il datore non partecipa a priorità e risorse: individuare cosa resta in capo al datore.',jsonb_build_array('Considerare RSPP o consulente sostituti del datore.','Non verificare competenze e disponibilità delle figure nominate.','Confondere supporto tecnico con trasferimento degli obblighi non delegabili.'),jsonb_build_array('normattiva-dlgs81-vigente','mlps-asr-2025','piemonte-indicazioni-formazione-2025')),
 ('datore:delega-responsabilita-231','Usare la delega come strumento organizzativo reale: oggetto, competenze, poteri, risorse e controllo dell’assetto.','Delega su manutenzioni e sicurezza senza budget autonomo né potere di fermare impianti: valutare tenuta e correttivi.',jsonb_build_array('Delegare compiti senza poteri o risorse.','Usare formule generiche.','Credere che la delega elimini ogni dovere di organizzazione del sistema.'),jsonb_build_array('normattiva-dlgs81-vigente','mlps-asr-2025','piemonte-indicazioni-formazione-2025','inail-sgsl','inail-mog-art30-2026')),
 ('datore:istituzioni-vigilanza-inclusione','Integrare sistema istituzionale, vigilanza e tutela delle persone vulnerabili, includendo prevenzione di violenze e molestie.','Aggressioni verbali e criticità per una lavoratrice con disabilità vengono trattate come casi individuali: costruire una risposta organizzativa.',jsonb_build_array('Ridurre inclusione e vulnerabilità a pratiche amministrative.','Gestire aggressioni solo come conflitti personali.','Non collegare segnalazioni e accomodamenti alla valutazione dei rischi.'),jsonb_build_array('normattiva-dlgs81-vigente','mlps-asr-2025','piemonte-indicazioni-formazione-2025','inail-violence-work-2025')),
 ('datore:standard-tecnici-documentazione','Governare conformità tecnico-strutturale e documentazione come sistema vivo di scadenze, manutenzioni, modifiche ed evidenze.','Impianto con certificazione iniziale regolare ma manutenzione scaduta e modifiche non tracciate: stabilire il gate di conformità.',jsonb_build_array('Confondere certificazione iniziale e conformità permanente.','Archiviare senza scadenziario.','Non riesaminare dopo modifiche tecniche.'),jsonb_build_array('normattiva-dlgs81-vigente','mlps-asr-2025','piemonte-indicazioni-formazione-2025')),
 ('datore:valutazione-rischi-misure','Trasformare il DVR in ciclo decisionale: priorità, misure, owner, risorse, scadenze e verifica di efficacia.','Misura strutturale rinviata per budget e sostituita temporaneamente: definire condizioni, durata, responsabilità e escalation.',jsonb_build_array('Chiudere azioni senza verificarne efficacia.','Usare misure temporanee senza scadenza.','Non assegnare risorsa o responsabile.'),jsonb_build_array('normattiva-dlgs81-vigente','mlps-asr-2025','piemonte-indicazioni-formazione-2025','inail-stress-methodology-2025')),
 ('datore:protezione-collettiva-gruppi','Applicare la gerarchia delle misure privilegiando protezione collettiva e organizzativa e considerando gruppi esposti a rischi particolari.','Per un rischio diffuso si propone subito un DPI più performante: confrontare eliminazione, protezione collettiva, organizzazione e DPI.',jsonb_build_array('Usare il DPI come prima scelta automatica.','Valutare un lavoratore medio astratto.','Non verificare compatibilità e uso reale dei DPI.'),jsonb_build_array('normattiva-dlgs81-vigente','mlps-asr-2025','piemonte-indicazioni-formazione-2025','inail-stress-methodology-2025')),
 ('datore:risorse-cambiamento-pianificazione','Gestire il cambiamento prima dell’esposizione: rischi, risorse, competenze, tempi e responsabilità devono essere riesaminati prima dell’avvio.','Nuovo turno e tecnologia automatizzata introdotti in due settimane: costruire la checklist decisionale prima dell’avvio.',jsonb_build_array('Valutare il cambiamento solo dopo l’avvio.','Separare progetto produttivo e prevenzione.','Non finanziare le misure insieme al cambiamento.'),jsonb_build_array('normattiva-dlgs81-vigente','mlps-asr-2025','piemonte-indicazioni-formazione-2025','inail-stress-methodology-2025')),
 ('datore:appalti-duvri-interferenze','Governare affidamenti e interferenze prima dell’ingresso operativo: qualificazione, informazioni, coordinamento, DUVRI quando dovuto e verifica sul campo.','Due imprese lavorano nello stesso reparto con attività singolarmente compatibili ma interferenti: definire coordinamento e gate di avvio.',jsonb_build_array('Trattare il DUVRI come documento statico.','Scambiare informazioni generiche.','Non aggiornare il coordinamento quando cambia il lavoro.'),jsonb_build_array('normattiva-dlgs81-vigente','mlps-asr-2025','piemonte-indicazioni-formazione-2025','inail-sgsl')),
 ('datore:emergenze-primo-soccorso-incendio','Organizzare emergenze come capacità operativa: scenari, incarichi, dotazioni, comunicazioni, prove e continuità dei presidi.','Prova di evacuazione: turno serale senza due ruoli chiave e percorso parzialmente ostruito. Definire correzioni immediate e strutturali.',jsonb_build_array('Considerare sufficiente il piano scritto.','Non verificare turni e assenze.','Non chiudere le azioni emerse dalle prove.'),jsonb_build_array('normattiva-dlgs81-vigente','mlps-asr-2025','piemonte-indicazioni-formazione-2025')),
 ('datore:sorveglianza-sanitaria-flussi','Integrare sorveglianza sanitaria nel processo organizzativo rispettando ruoli e riservatezza: esposizioni, giudizi, limitazioni e azioni.','Giudizio con limitazioni ricevuto ma mansione non modificata subito: disegnare il flusso organizzativo corretto.',jsonb_build_array('Trattare la sorveglianza sanitaria come adempimento isolato.','Condividere dati sanitari non necessari.','Ritardare l’attuazione di limitazioni o prescrizioni.'),jsonb_build_array('normattiva-dlgs81-vigente','mlps-asr-2025','piemonte-indicazioni-formazione-2025')),
 ('datore:informazione-formazione-consultazione','Progettare informazione, formazione, addestramento e consultazione in funzione di rischi e cambiamenti, verificando comprensione e trasferimento al lavoro.','Procedura modificata tramite circolare senza verifica di comprensione: definire percorso formativo e consultazione necessari.',jsonb_build_array('Usare la firma presenza come prova di efficacia.','Aggiornare documenti senza competenze.','Coinvolgere RLS e lavoratori solo a decisioni concluse.'),jsonb_build_array('normattiva-dlgs81-vigente','mlps-asr-2025','piemonte-indicazioni-formazione-2025')),
 ('datore:vigilanza-procedure-efficacia','Definire un sistema di vigilanza che osservi lavoro reale, deviazioni e cause organizzative e chiuda il ciclo con verifica di efficacia.','La stessa deviazione compare in tre squadre: superare il richiamo individuale e individuare cosa non funziona nel sistema.',jsonb_build_array('Ridurre la vigilanza ai richiami individuali.','Non analizzare deviazioni ricorrenti.','Considerare efficace una procedura mai osservata sul campo.'),jsonb_build_array('normattiva-dlgs81-vigente','mlps-asr-2025','inail-condivido-near-miss','inail-sgsl')),
 ('datore:mog-sistemi-gestione','Comprendere MOG e SGSL come sistemi di governo: politica, ruoli, processi, controlli, audit, azioni correttive e riesame.','Procedure e organigramma esistono ma azioni di audit restano aperte e il riesame non incide sul budget: valutare attuazione reale.',jsonb_build_array('Confondere manuale o certificazione con attuazione.','Non collegare audit e riesame a decisioni e risorse.','Costruire un modello scollegato dai processi reali.'),jsonb_build_array('normattiva-dlgs81-vigente','mlps-asr-2025','piemonte-indicazioni-formazione-2025','inail-sgsl','inail-mog-art30-2026')),
 ('datore:costi-benefici-indicatori','Usare indicatori leading e lagging per orientare priorità e risorse, rendendo visibili segnali anticipatori e costi della mancata sicurezza.','Infortuni in calo ma near miss, manutenzioni arretrate e azioni scadute aumentano: decidere se il sistema sta davvero migliorando.',jsonb_build_array('Misurare solo infortuni.','Premiare numeri bassi che possono nascondere mancata segnalazione.','Raccogliere KPI senza soglie e decisioni associate.'),jsonb_build_array('normattiva-dlgs81-vigente','mlps-asr-2025','inail-condivido-near-miss','inail-sgsl')),
 ('datore:comunicazione-scenario-governance','Integrare comunicazione, risorse, priorità e verifica in una decisione completa di governance.','Near miss grave, manutenzione rinviata e pressione produttiva: costruire un decision record con misura, owner, budget, scadenza e verifica.',jsonb_build_array('Decidere senza esplicitare il rischio residuo.','Assegnare azioni senza risorse o scadenze.','Comunicare senza verificare l’attuazione.'),jsonb_build_array('normattiva-dlgs81-vigente','mlps-asr-2025','inail-condivido-near-miss','inail-sgsl')),
 ('agg-datore:novita-cambiamenti','Aggiornare il sistema partendo dai cambiamenti del quinquennio: norme, processi, tecnologie, organizzazione, persone e modalità di lavoro.','Lavoro ibrido, nuova tecnologia e riorganizzazione: individuare parti di DVR, procedure, competenze e responsabilità da riesaminare.',jsonb_build_array('Fare un riepilogo normativo senza impatto sul contesto.','Ignorare cambiamenti graduali.','Non chiudere con azioni e responsabilità.'),jsonb_build_array('normattiva-dlgs81-vigente','mlps-asr-2025','piemonte-indicazioni-formazione-2025','inail-stress-methodology-2025')),
 ('agg-datore:rischi-dvr-misure','Riesaminare DVR e misure alla luce di rischi emergenti, evidenze del periodo e trasformazioni del lavoro.','Più automazione e lavoro da remoto, con indicatori di stress peggiori: individuare cosa rivalutare e quali misure testare.',jsonb_build_array('Aggiungere rischi al DVR senza modificare misure.','Trattare rischi psicosociali come tema individuale.','Non verificare efficacia delle nuove misure.'),jsonb_build_array('normattiva-dlgs81-vigente','mlps-asr-2025','piemonte-indicazioni-formazione-2025','inail-stress-methodology-2025')),
 ('agg-datore:eventi-nearmiss-indicatori','Usare infortuni, near miss, audit e indicatori come fonti per decidere prima che gli scostamenti producano danno.','Tre near miss simili senza infortuni: ricostruire fattori tecnici, organizzativi e procedurali e definire correttivi verificabili.',jsonb_build_array('Archiviare i near miss perché senza danno.','Ricercare subito un colpevole.','Chiudere azioni senza criterio di efficacia.'),jsonb_build_array('normattiva-dlgs81-vigente','mlps-asr-2025','inail-condivido-near-miss','inail-sgsl')),
 ('agg-datore:organizzazione-competenze','Riesaminare ruoli, competenze, formazione e vigilanza rispetto all’organizzazione attuale.','Cambiati responsabili, turni e mansioni ma organigramma, deleghe e percorsi formativi sono invariati: costruire il riallineamento.',jsonb_build_array('Aggiornare solo l’organigramma grafico.','Non verificare competenze effettive.','Confondere attestato valido con competenza adeguata al compito attuale.'),jsonb_build_array('normattiva-dlgs81-vigente','mlps-asr-2025','piemonte-indicazioni-formazione-2025')),
 ('agg-datore:appalti-emergenze-cambiamenti','Riesaminare appalti ed emergenze quando cambiano imprese, layout, turni, attività o scenari, verificando coordinamento e capacità operativa.','Nuovo appaltatore opera in un turno prima non coperto e modifica accessi e viabilità: aggiornare interferenze, emergenze e coordinamento.',jsonb_build_array('Riutilizzare documenti del precedente appalto.','Non integrare appaltatori nelle emergenze.','Ignorare cambi di turno o layout.'),jsonb_build_array('normattiva-dlgs81-vigente','mlps-asr-2025','piemonte-indicazioni-formazione-2025','inail-sgsl'))
), base as (
 select lu.id learning_unit_id,lu.stable_key,v.content,a.focus,a.scenario,a.errors,a.source_keys
 from authored a
 join public.learning_units lu on lu.stable_key=a.stable_key
 join public.learning_unit_versions v on v.learning_unit_id=lu.id and v.version_number=1
), enriched as (
 select learning_unit_id,stable_key,source_keys,
 content || jsonb_build_object(
   'focus',focus,'case',scenario,'common_errors',errors,'didactic_version','datore-authored-v3',
   'question_explanation',coalesce(content->>'question_explanation',content->>'detail',content->>'summary'),
   'takeaway',coalesce(content->>'takeaway',content->>'summary'),
   'teacher_activity',jsonb_build_object('prompt',scenario,'method','Prima raccolta dei fatti e delle decisioni dell’aula; poi confronto con obblighi, poteri, misure e criteri di verifica.','debrief','Chiudere sempre con cosa fare, chi coinvolgere, condizione di STOP e quale evidenza dimostra l’efficacia.'),
   'operational',coalesce(content->'operational','{}'::jsonb)||jsonb_build_object('before',jsonb_build_array('Raccogli evidenze, cambiamenti e vincoli pertinenti.','Chiarisci ruoli, poteri, risorse e misure già previste.'),'during',jsonb_build_array('Confronta lavoro reale e assetto previsto.','Decidi misura, responsabilità e risorsa.','Gestisci gli scostamenti ed effettua escalation quando necessario.'),'after',jsonb_build_array('Verifica attuazione ed efficacia.','Registra evidenze e riesamina il rischio residuo e le azioni aperte.'),'if_problem',jsonb_build_array('Proteggi immediatamente persone e attività esposte.','Non normalizzare lo scostamento.','Attiva le funzioni competenti e il livello decisionale adeguato.'),'who_to_involve',jsonb_build_array('RSPP/SPP','Dirigenti e preposti','RLS quando pertinente','Medico competente quando pertinente','Funzioni tecniche/HR/acquisti secondo il caso'),'stop_conditions',coalesce(content->'operational'->'stop_conditions',jsonb_build_array('Rischio grave non controllato.','Misura essenziale assente o inefficace.','Responsabilità o risorse critiche non definite.')),'adaptation','Adattare esempi e procedure al DVR, all’assetto organizzativo, ai poteri effettivi e alle evidenze dell’azienda.'),
   'formative_check',jsonb_build_object('question',coalesce(content->>'question',content->>'summary'),'explanation',coalesce(content->>'question_explanation',content->>'detail',content->>'summary'),'formative_only',true,'test_builder_excluded',true),
   'graphic_cards',jsonb_build_array(jsonb_build_object('title','Decisione da portare a casa','body',focus),jsonb_build_object('title','Scenario per l’aula','body',scenario)),
   'source_keys',source_keys,
   'source_audit',jsonb_build_object('status','reviewed','checked_on','2026-10-16','reuse_policy','reference_and_original_rewrite','normative_validation','D.Lgs. 81/2008 vigente + Accordo Stato-Regioni 17/04/2025 Rep. 59/CSR'),
   'source_integration_note','Fonti normative e tecniche usate per validazione e metodo; testi, casi e sequenze operative SafetyTraining sono originali. Le verifiche interne sono formative e separate dal Test Builder.',
   'quality',coalesce(content->'quality','{}'::jsonb)||jsonb_build_object('teacher_ready',true,'learner_ready',true,'decision_based',true,'transfer_to_work',true,'authored_presentation',true,'question_has_explanation',true,'formative_checks_only',true,'final_assessment',false,'test_builder_excluded',true),
   'final_assessment',false
 ) new_content
 from base
), final_content as (
 select e.learning_unit_id,e.stable_key,e.source_keys,e.new_content||jsonb_build_object('evidence_sources',coalesce((select jsonb_agg(jsonb_build_object('source_key',ts.source_key,'authority',ts.authority,'title',ts.title,'url',ts.canonical_url,'checked_on','2026-10-16','use','authored_evidence') order by ts.source_key) from jsonb_array_elements_text(e.source_keys) sk(source_key) join public.training_sources ts on ts.source_key=sk.source_key),'[]'::jsonb)) new_content
 from enriched e
)
insert into public.learning_unit_versions(learning_unit_id,version_number,status,content,content_hash,published_at)
select learning_unit_id,2,'draft',new_content,md5(new_content::text),null from final_content
on conflict (learning_unit_id,version_number) do update set status='draft',content=excluded.content,content_hash=excluded.content_hash,published_at=null;

with lu as (select id from public.learning_units where stable_key='agg-datore:governance-riesame'), c as (
 select jsonb_build_object('title','ADL06 · Governance e riesame del sistema di prevenzione','summary','L’aggiornamento generale si chiude traducendo criticità e cambiamenti in un piano di miglioramento verificabile, senza includere i contenuti del modulo Cantieri.','detail','Il datore ordina le priorità, assegna risorse e responsabilità, definisce scadenze, indicatori ed evidenze di chiusura. Il riesame verifica se le decisioni adottate stanno riducendo il rischio e se sono necessari ulteriori interventi.','focus','Governance generale e riesame: priorità → decisione → risorsa → owner → scadenza → indicatore → verifica.','case','Dal corso emergono sei criticità e risorse limitate. Costruire un portafoglio di azioni con priorità, owner, budget, scadenza, indicatore e data di riesame.','question','Quando un aggiornamento può dirsi realmente trasferito nella gestione aziendale?','question_explanation','Quando produce decisioni osservabili e verificabili: ogni priorità deve avere misura, risorsa, responsabile, scadenza e criterio di efficacia, con successivo riesame.','common_errors',jsonb_build_array('Chiudere il corso senza decisioni operative.','Assegnare priorità senza risorse.','Confondere il riesame con un semplice verbale conclusivo.'),'teacher_expansion',jsonb_build_array('[0–10 min] Sintesi dei cambiamenti e delle criticità emerse.','[10–25 min] Priorità e rischio residuo.','[25–40 min] Risorse, owner e scadenze.','[40–50 min] Indicatori ed evidenze di efficacia.','[50–60 min] Decision record e data di riesame.'),'teacher_activity',jsonb_build_object('prompt','Trasformare sei criticità in un piano di azione prioritizzato.','method','Lavoro su decision record: fatto, rischio, misura, owner, risorsa, scadenza, indicatore.','debrief','Nessuna azione critica può restare senza responsabile, risorsa o criterio di verifica.'),'operational',jsonb_build_object('objective','Tradurre l’aggiornamento in un piano di miglioramento verificabile.','step_by_step',jsonb_build_array('Raccogli criticità','Prioritizza','Decidi la misura','Assegna owner','Assegna risorsa','Fissa scadenza','Definisci indicatore','Verifica','Riesamina'),'stop_conditions',jsonb_build_array('Criticità rilevante senza owner.','Azione critica senza risorsa o scadenza.','Nessun criterio per verificare l’efficacia.'),'who_to_involve',jsonb_build_array('RSPP/SPP','Dirigenti e preposti','RLS quando pertinente','Funzioni aziendali coinvolte'),'adaptation','Usare criticità ed evidenze reali dell’organizzazione, senza includere contenuti del modulo Cantieri.'),'formative_check',jsonb_build_object('question','Qual è il segnale che il riesame non è solo formale?','explanation','Il riesame è sostanziale quando modifica priorità, risorse, misure o responsabilità sulla base di evidenze e ne verifica successivamente l’efficacia.','formative_only',true,'test_builder_excluded',true),'graphic_cards',jsonb_build_array(jsonb_build_object('title','Decision record','body','Criticità → rischio → misura → owner → risorsa → scadenza → indicatore → verifica.'),jsonb_build_object('title','Separazione Cantieri','body','L’aggiornamento generale resta autonomo; i temi Cantieri si aggiungono solo quando ricorrono le condizioni previste dall’ASR 2025.')),'didactic_version','datore-authored-v3','source_keys',jsonb_build_array('normattiva-dlgs81-vigente','mlps-asr-2025','piemonte-indicazioni-formazione-2025','inail-condivido-near-miss','inail-sgsl'),'source_audit',jsonb_build_object('status','reviewed','checked_on','2026-10-16','reuse_policy','reference_and_original_rewrite','normative_validation','D.Lgs. 81/2008 vigente + Accordo Stato-Regioni 17/04/2025 Rep. 59/CSR'),'source_integration_note','La LU sostituisce come candidata la precedente unità mista governance/Cantieri. Il modulo Cantieri resta separato e condizionale. Test Builder escluso.','quality',jsonb_build_object('teacher_ready',true,'learner_ready',true,'decision_based',true,'transfer_to_work',true,'authored_presentation',true,'question_has_explanation',true,'formative_checks_only',true,'final_assessment',false,'test_builder_excluded',true,'construction_module_separated',true),'final_assessment',false) content
)
insert into public.learning_unit_versions(learning_unit_id,version_number,status,content,content_hash,published_at)
select lu.id,1,'draft',c.content||jsonb_build_object('evidence_sources',(select jsonb_agg(jsonb_build_object('source_key',ts.source_key,'authority',ts.authority,'title',ts.title,'url',ts.canonical_url,'checked_on','2026-10-16','use','authored_evidence') order by ts.source_key) from jsonb_array_elements_text(c.content->'source_keys') sk(source_key) join public.training_sources ts on ts.source_key=sk.source_key)),md5((c.content||jsonb_build_object('evidence_sources',(select jsonb_agg(jsonb_build_object('source_key',ts.source_key,'authority',ts.authority,'title',ts.title,'url',ts.canonical_url,'checked_on','2026-10-16','use','authored_evidence') order by ts.source_key) from jsonb_array_elements_text(c.content->'source_keys') sk(source_key) join public.training_sources ts on ts.source_key=sk.source_key)))::text),null from lu,c
on conflict (learning_unit_id,version_number) do update set status='draft',content=excluded.content,content_hash=excluded.content_hash,published_at=null;

with authored as (
 select lu.id learning_unit_id,luv.content->'source_keys' source_keys
 from public.learning_units lu join public.learning_unit_versions luv on luv.learning_unit_id=lu.id
 where luv.content->>'didactic_version'='datore-authored-v3' and luv.status='draft'
)
insert into public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
select a.learning_unit_id,sk.source_key,'authored_evidence_v3','Fonte usata per validazione normativa, approfondimento tecnico o metodo nella versione authored-v3 Datore di lavoro.',date '2026-10-16',jsonb_build_object('didactic_version','datore-authored-v3','reuse_policy','reference_and_original_rewrite')
from authored a cross join lateral jsonb_array_elements_text(a.source_keys) sk(source_key)
join public.training_sources ts on ts.source_key=sk.source_key
on conflict (learning_unit_id,source_key,purpose) do update set relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;

-- Safety invariant: do not link the new drafts into any existing course composition.
do $$ declare n integer; links integer; begin
 select count(*) into n from public.learning_unit_versions luv join public.learning_units lu on lu.id=luv.learning_unit_id where luv.content->>'didactic_version'='datore-authored-v3' and luv.status='draft';
 if n < 22 then raise exception 'v20.071 expected at least 22 datore-authored-v3 drafts, got %',n; end if;
 select count(*) into links from public.course_module_units cmu join public.learning_unit_versions luv on luv.id=cmu.unit_version_id where luv.content->>'didactic_version'='datore-authored-v3';
 if links <> 0 then raise exception 'v20.071 authored drafts unexpectedly linked: %',links; end if;
end $$;
